const uname=r=>(uniOf(r)||{}).nombre||'Sin unidad';
const sname=r=>(get('sedes',r.sedeId)||{}).nombre||'—';
const ename=r=>(get('empresas',r.empresaId)||{}).nombre||'—';
function areaOf(r){let x=uniOf(r),n=0;const g=id=>get('unidades',id);while(x&&x.padreId&&g(x.padreId)&&g(x.padreId).padreId&&n++<20)x=g(x.padreId);return x}
const aname=r=>(areaOf(r)||{}).nombre||'Sin unidad';
function unitSet(id){const s=[id];let i=0;while(i<s.length){T().unidades.forEach(u=>{if(u.padreId===s[i]&&!s.includes(u.id))s.push(u.id)});i++}return s}
const sel=(attr,val,opts,all)=>`<select class="in" ${attr}>${all===false?'':`<option value="">${esc(all||'Todos')}</option>`}${opts.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${esc(a[0])}"${String(val)===String(a[0])?' selected':''}>${esc(a[1])}</option>`}).join('')}</select>`;
const goSafe=(r,x)=>{if(allowed(r))go(r,x||{});else toast('Tu rol no tiene acceso a esa pantalla')};
const MODN={tiempo:'Tiempo y asistencia',nomina:'Nómina',reclutamiento:'Reclutamiento',desempeno:'Desempeño',aprendizaje:'Aprendizaje',experiencia:'Experiencia',documentos:'Documentos',mesa:'Mesa de ayuda',sst:'Seguridad y salud en el trabajo',gastos:'Gastos',onboarding:'Onboarding',compensacion:'Compensación'};
const modName=id=>(MODS.find(m=>m.id===id)||{}).nombre||MODN[id]||id;
const sinGente=()=>!T().relaciones.length?`<div class="panel">${emptyState('Aún no hay colaboradores','Los indicadores, tableros y alertas se calculan con las fichas. Registra el primer ingreso y vuelve aquí.',can('colaborador.crear')?'<button class="btn p" data-a="newColab">Nuevo colaborador</button>':'')}</div>`:'';
const hasA=()=>mOn('analytics'),hasIA=()=>mOn('ia');
const csvTxt=(heads,rows)=>{const q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"';return [heads.map(q).join(',')].concat(rows.map(r=>r.map(q).join(','))).join('\n')};
const strip=h=>String(h==null?'':h).replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim();
