/* ---------- gráficos SVG (coordenadas en %, nítidos a cualquier ancho y en ambos temas) ---------- */
const SER=[['var(--accent)',1],['var(--warn)',1],['var(--ok)',1],['var(--crit)',1],['var(--muted)',1],['var(--accent)',.45],['var(--warn)',.45],['var(--ok)',.45]];
const sw=i=>`<i class="in_sw" style="background:${SER[i%8][0]};opacity:${SER[i%8][1]}"></i>`;
const legend=ns=>`<div class="in_leg">${ns.map((n,i)=>`<span>${sw(i)}${esc(n)}</span>`).join('')}</div>`;
function nice(mx){if(mx<=4)return Math.max(1,Math.ceil(mx))||1;const p=Math.pow(10,Math.floor(Math.log10(mx))),f=mx/p;return (f<=1?1:f<=2?2:f<=5?5:10)*p}
function grid(mx,H,top,bot,fmt){let o='';(mx<=4&&mx%2?[0,1]:[0,.5,1]).forEach(t=>{const y=top+(H-top-bot)*(1-t);o+=`<line x1="0" x2="100%" y1="${y}" y2="${y}" stroke="var(--line)" stroke-width="1"/><text x="0" y="${y-3}">${esc((fmt||n1)(mx*t))}</text>`});return o}
function svgLine(series,labels,o){o=o||{};const H=o.h||190,top=16,bot=22,n=labels.length,all=series.reduce((a,s)=>a.concat(s.vals.filter(v=>v!=null)),[]);if(!n||!all.length)return'<p class="muted">Sin datos para graficar.</p>';
 const mn=o.min!=null?o.min:0,mx=o.max!=null?o.max:nice(Math.max(...all,1)),X=i=>n===1?50:6+i*(90/(n-1)),Y=v=>top+(H-top-bot)*(1-(v-mn)/((mx-mn)||1)),step=Math.ceil(n/7);
 let s=`<svg class="in_svg" width="100%" height="${H}" role="img" aria-label="${esc(o.aria||'Gráfico de líneas')}">`;
 [0,.5,1].forEach(t=>{const y=top+(H-top-bot)*(1-t);s+=`<line x1="0" x2="100%" y1="${y}" y2="${y}" stroke="var(--line)" stroke-width="1"/><text x="0" y="${y-3}">${esc((o.fmt||n1)(mn+(mx-mn)*t))}</text>`});
 labels.forEach((l,i)=>{if(i%step===0||i===n-1&&(n-1)%step>step/2)s+=`<text x="${X(i)}%" y="${H-5}" text-anchor="${i===0?'start':i===n-1?'end':'middle'}">${esc(l)}</text>`});
 series.forEach((se,k)=>{const pts=se.vals.map((v,i)=>v==null?null:[X(i),Y(v)]).filter(Boolean);
  s+=`<svg x="0" y="0" width="100%" height="${H}" viewBox="0 0 100 ${H}" preserveAspectRatio="none" style="overflow:visible"><polyline points="${pts.map(p=>p[0].toFixed(2)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${SER[k][0]}" stroke-opacity="${SER[k][1]}" stroke-width="2" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>`;
  se.vals.forEach((v,i)=>{if(v==null)return;s+=`<circle cx="${X(i)}%" cy="${Y(v).toFixed(1)}" r="${n>16?2.5:3.5}" fill="${SER[k][0]}" stroke="var(--surface)" stroke-width="1.5"><title>${esc(labels[i]+' · '+se.n+': '+(o.fmt||n1)(v))}</title></circle>`});
  const li=se.vals.length-1,lv=se.vals[li];if(lv!=null)s+=`<text class="in_vl" x="${X(li)}%" y="${(Y(lv)-8).toFixed(1)}" text-anchor="end">${esc((o.fmt||n1)(lv))}</text>`});
 return s+'</svg>'+(series.length>1?legend(series.map(x=>x.n)):'')}
function svgBars(series,labels,o){o=o||{};const H=o.h||190,top=16,bot=22,n=labels.length,k=series.length;if(!n)return'<p class="muted">Sin datos para graficar.</p>';
 const tot=i=>sum(series,s=>s.vals[i]),mx=nice(Math.max(1,...(o.stack?labels.map((_,i)=>tot(i)):series.reduce((a,s)=>a.concat(s.vals),[])))),slot=94/n,bw=o.stack?slot*.62:slot*.72/k,step=Math.ceil(n/8),ph=H-top-bot;
 let s=`<svg class="in_svg" width="100%" height="${H}" role="img" aria-label="${esc(o.aria||'Gráfico de barras')}">`+grid(mx,H,top,bot,o.fmt);
 labels.forEach((l,i)=>{const x0=6+i*slot+(slot-(o.stack?bw:bw*k))/2;let acc=0;
  series.forEach((se,j)=>{const v=se.vals[i]||0,h=v/mx*ph,y=o.stack?top+ph-acc-h:top+ph-h,x=o.stack?x0:x0+j*bw;acc+=h;if(v)s+=`<rect x="${x.toFixed(2)}%" y="${y.toFixed(1)}" width="${(bw*(o.stack?1:.9)).toFixed(2)}%" height="${Math.max(h,1.5).toFixed(1)}" rx="2" fill="${SER[j][0]}" fill-opacity="${SER[j][1]}"><title>${esc(l+' · '+se.n+': '+(o.fmt||n1)(v))}</title></rect>`;
   if(!o.stack&&v&&n*k<=14)s+=`<text class="in_vl" x="${(x+bw*.45).toFixed(2)}%" y="${(y-4).toFixed(1)}" text-anchor="middle">${esc((o.fmt||n1)(v))}</text>`});
  if(o.stack&&tot(i)&&n<=14)s+=`<text class="in_vl" x="${(x0+bw/2).toFixed(2)}%" y="${(top+ph-acc-4).toFixed(1)}" text-anchor="middle">${esc((o.fmt||n1)(tot(i)))}</text>`;
  if(i%step===0){const mxc=Math.max(5,Math.floor(44/Math.ceil(n/step))),lt=String(l);s+=`<text x="${(6+i*slot+slot/2).toFixed(2)}%" y="${H-5}" text-anchor="middle">${esc(lt.length>mxc?lt.slice(0,mxc-1)+'…':lt)}<title>${esc(lt)}</title></text>`}});
 return s+'</svg>'+(k>1?legend(series.map(x=>x.n)):'')}
/* barras horizontales apiladas: una fila por categoría, segmentos por serie */
function svgStackH(rows,names){const mx=Math.max(1,...rows.map(r=>sum(r.v,x=>x)));
 return `<div class="in_hb">${rows.map(r=>{let acc=0;const t=sum(r.v,x=>x);return `<div><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><span style="min-width:0;overflow-wrap:anywhere">${esc(r.l)}</span><b class="num">${n1(t)}</b></div><svg class="in_svg" width="100%" height="12" role="img" aria-label="${esc(r.l+': '+r.v.map((v,i)=>names[i]+' '+v).join(', '))}"><rect x="0" y="0" width="100%" height="12" rx="3" fill="var(--surface2)"/>${r.v.map((v,i)=>{const w=v/mx*100,x=acc;acc+=w;return v?`<rect x="${x.toFixed(2)}%" y="0" width="${Math.max(w-.4,.4).toFixed(2)}%" height="12" rx="2" fill="${SER[i%8][0]}" fill-opacity="${SER[i%8][1]}"><title>${esc(names[i]+': '+v)}</title></rect>`:''}).join('')}</svg></div>`}).join('')}</div>${legend(names)}`}
function hbars(items,o){o=o||{};if(!items.length)return'<p class="muted">Sin datos para mostrar.</p>';const mx=Math.max(1,...items.map(x=>x.v));
 return `<div class="in_hb">${items.map(x=>{const inner=`<div class="row" style="justify-content:space-between;flex-wrap:nowrap"><span style="min-width:0;overflow-wrap:anywhere">${esc(x.l)}</span><b class="num" style="white-space:nowrap">${x.t!=null?x.t:n1(x.v)}</b></div><div class="bar"><i style="width:${Math.max(0,x.v)/mx*100}%${x.tone?';background:var(--'+x.tone+')':''}"></i></div>`;return x.a?`<button ${x.a} title="Ver las personas detrás del número">${inner}</button>`:`<div>${inner}</div>`}).join('')}</div>`}
function donut(parts,center){const tot=sum(parts,p=>p.v);if(!tot)return'<p class="muted">Sin datos para mostrar.</p>';let off=25,s='';
 parts.forEach((p,i)=>{const pc=p.v/tot*100;s+=`<circle cx="21" cy="21" r="15.915" fill="none" stroke="${p.col||SER[i%8][0]}" stroke-opacity="${p.col?1:SER[i%8][1]}" stroke-width="6" stroke-dasharray="${Math.max(pc-.8,.2).toFixed(2)} ${(100-Math.max(pc-.8,.2)).toFixed(2)}" stroke-dashoffset="${off.toFixed(2)}"><title>${esc(p.l+': '+p.v)}</title></circle>`;off-=pc});
 return `<div class="in_donut"><svg class="in_svg" viewBox="0 0 42 42" width="116" height="116" role="img" aria-label="${esc(parts.map(p=>p.l+' '+p.v).join(', '))}" style="flex:none">${s}<text x="21" y="20.5" text-anchor="middle" style="font-size:8px;font-weight:700;fill:var(--ink);font-family:var(--f-display)">${esc(center==null?tot:center)}</text><text x="21" y="26" text-anchor="middle" style="font-size:3.2px">total</text></svg>
 <div style="display:flex;flex-direction:column;gap:6px;flex:1 1 170px;min-width:0">${parts.map((p,i)=>{const inner=`${p.col?`<i class="in_sw" style="background:${p.col}"></i>`:sw(i)}<span style="flex:1;min-width:0;text-align:left">${esc(p.l)}</span><b class="num">${p.v}</b><span class="muted num" style="width:44px;text-align:right">${n1(p.v/tot*100,0)} %</span>`;return p.a?`<button class="in_lnk" style="display:flex;gap:8px;align-items:center;width:100%;text-decoration:none;color:inherit;font-weight:400;font-size:13.5px" ${p.a}>${inner}</button>`:`<div class="row" style="flex-wrap:nowrap">${inner}</div>`}).join('')}</div></div>`}
function spark(vals){const n=vals.length;if(n<2)return'';const mx=Math.max(...vals),mn=Math.min(...vals);if(mx===mn)return'';const Y=v=>30-(mx===mn?13:(v-mn)/(mx-mn)*26);
 return `<svg class="in_spark" viewBox="0 0 100 34" preserveAspectRatio="none" aria-hidden="true"><polyline points="${vals.map((v,i)=>(i*100/(n-1)).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}" fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg>`}
