function vConstructor(){if(!can(PRC))return `<div class="panel">${emptyState('No puedes crear reportes','Tu rol no tiene el permiso para armar reportes personalizados.','<button class="btn" data-a="nav" data-r="in_reportes">Volver a Reportes</button>')}</div>`;
 const b=ui.in_b||(ui.in_b=newB());if(!srcOk(b.src))b.src='col';const s=SRC[b.src],fs=s.f.filter(fOk),nums=fs.filter(f=>f[2]==='n'),res=runDef(b);
 const step=(n,t,sub,body)=>`<div class="panel"><div class="pb in_step"><span class="in_num">${n}</span><div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:10px"><div><h3>${t}</h3><span class="muted" style="font-size:12.5px">${sub}</span></div>${body}</div></div></div>`;
 const fSel=(attr,val,list,vac)=>sel(attr,val,list.map(f=>[f[0],f[1]]),vac);
 const filt=b.filters.map((x,i)=>{const f=fld(b.src,x.f)||fs[0],vals=f[2]==='t'?[...new Set(s.rows().map(r=>String(f[3](r))))].filter(Boolean).sort((a,c)=>a.localeCompare(c,'es')):[];
  return `<div class="row">${fSel(`id="in_bff${i}" data-inb="ff" data-ix="${i}" style="width:auto;flex:1 1 150px"`,f[0],fs,false)}${sel(`id="in_bfo${i}" data-inb="fo" data-ix="${i}" style="width:auto;flex:0 1 150px"`,x.op,OPS[f[2]],false)}${f[2]==='t'&&vals.length&&vals.length<=25&&x.op!=='has'?sel(`id="in_bfv${i}" data-inb="fv" data-ix="${i}" style="width:auto;flex:1 1 150px"`,x.v,vals,'Elige un valor'):`<input class="in" id="in_bfv${i}" data-inb="fv" data-ix="${i}" type="${f[2]==='n'?'number':f[2]==='d'?'date':'text'}" value="${esc(x.v)}" placeholder="Valor" style="width:auto;flex:1 1 150px">`}<button class="btn s d" data-a="in_bFDel" data-i="${i}" aria-label="Quitar filtro">Quitar</button></div>`}).join('');
 const mets=b.metrics.map((m,i)=>`<div class="row">${sel(`id="in_bmf${i}" data-inb="mfn" data-ix="${i}" style="width:auto;flex:0 1 150px"`,m.fn,Object.entries(FN).filter(e=>e[0]==='count'||nums.length),false)}${m.fn!=='count'?fSel(`id="in_bmc${i}" data-inb="mf" data-ix="${i}" style="width:auto;flex:1 1 180px"`,m.f,nums,false):'<span class="muted" style="flex:1 1 180px">Número de filas del grupo</span>'}<button class="btn s d" data-a="in_bMDel" data-i="${i}" aria-label="Quitar métrica">Quitar</button></div>`).join('');
 let prev;if(res.err)prev=`<div class="err">${esc(res.err)}</div>`;else if(!res.cols.length)prev=emptyState('Elige al menos un campo','Marca los campos que quieres ver como columnas, o agrupa por un campo.');
 else prev=(b.viz==='barras'&&res.chart&&res.rows.length?`<div style="margin-bottom:14px">${res.chart.labels.length>7||res.chart.labels.some(l=>l.length>9)?hbars(res.chart.labels.map((l,i)=>({l,v:res.chart.vals[i]}))):svgBars([{n:res.chart.name,vals:res.chart.vals}],res.chart.labels,{aria:res.chart.name})}</div>`:'')+(res.rows.length?resTable({cols:res.cols,rows:res.rows.slice(0,10)},1,0)+`<p class="muted" style="margin-top:10px">${res.grouped?pl(res.rows.length,'grupo')+' a partir de '+pl(res.total,'fila'):'Mostrando '+Math.min(10,res.rows.length)+' de '+pl(res.total,'fila')}${res.tot&&res.tot.length?' · '+esc(res.tot.join(' · ')):''}.</p>`:'<p class="muted">Ninguna fila cumple los filtros.</p>');
 return `<div class="crumb"><a href="#" data-a="nav" data-r="in_reportes">Reportes</a> / Constructor</div>`+pageHead('Reportes',b.id?'Editar «'+b.nombre+'»':'Crear reporte','<button class="btn" data-a="in_bReset">Empezar de nuevo</button><button class="btn p" data-a="in_bSave">Guardar reporte</button>','Arma tu reporte en seis pasos. La vista previa se actualiza con cada cambio y siempre respeta tu alcance.')
 +`<div class="grid g2" style="align-items:start"><div class="in_steps">
 ${step(1,'Fuente de datos','¿Sobre qué quieres reportar? Solo ves las fuentes de módulos contratados y permitidos para tu rol.',sel('id="in_bSrc" data-inb="src"',b.src,Object.keys(SRC).filter(srcOk).map(k=>[k,SRC[k].n]),false)+`<span class="muted" style="font-size:12.5px">${esc(s.d)}.</span>`)}
 ${step(2,'Campos','Las columnas del reporte. Los campos sensibles solo aparecen si tu rol puede verlos.',`<div class="in_chips">${fs.map(f=>`<button class="in_chip ${b.fields.includes(f[0])?'on':''}" data-a="in_bField" data-k="${f[0]}" aria-pressed="${b.fields.includes(f[0])}">${esc(f[1])}${f[4]?' <span class="pill warn" style="padding:0 6px;font-size:10.5px">Sensible</span>':''}</button>`).join('')}</div>`)}
 ${step(3,'Filtros','Condiciones que deben cumplir las filas.',filt+'<div><button class="btn s" data-a="in_bFAdd">Agregar filtro</button></div>')}
 ${step(4,'Agrupación','Opcional: resume las filas por un campo. Las fechas se agrupan por mes.',fSel('id="in_bGrp" data-inb="group"',b.group,fs,'Sin agrupar (listado)'))}
 ${step(5,'Métricas',b.group?'Qué calcular para cada grupo.':'Sin agrupación se muestran como totales al pie del listado.',mets+'<div><button class="btn s" data-a="in_bMAdd">Agregar métrica</button></div>')}
 ${step(6,'Visualización','Cómo se presenta el resultado.',`<div class="row"><button class="btn ${b.viz==='tabla'?'p':''}" data-a="in_bViz" data-v="tabla">Tabla</button><button class="btn ${b.viz==='barras'?'p':''}" data-a="in_bViz" data-v="barras"${b.group?'':' disabled title="Las barras necesitan una agrupación"'}>Barras</button></div>${b.group?'':'<span class="muted" style="font-size:12.5px">Para ver barras, elige primero un campo de agrupación.</span>'}`)}
 </div><div class="panel" style="position:sticky;top:0"><div class="ph"><h2>Vista previa</h2>${res.err?'':pill(pl(res.total||0,'fila'),'acc')}</div><div class="pb">${prev}</div></div></div>`}

