function buscar(qr){const q=norm(qr).trim(),out=[];if(q.length<2)return out;const sc=scoped(),scIds=new Set(sc.map(r=>r.id)),my=myRel(),has=(...s)=>norm(s.join(' ')).includes(q),add=(cat,items)=>{if(items.length)out.push({cat,n:items.length,items:items.slice(0,8)})};
 const go_=(r,u)=>`data-a="in_go" data-r="${r}" data-u="${esc(JSON.stringify(u||{}))}"`;
 add('Personas',sc.filter(r=>has(nm(r),r.codigo,pto(r).nombre||'',per(r).correo)).map(r=>({t:nm(r),s:(pto(r).nombre||'')+' · '+uname(r)+' · '+r.estado,a:`data-a="ficha" data-id="${r.id}"`})).concat(can('directorio.ver')?T().relaciones.filter(r=>r.estado==='Activo'&&!scIds.has(r.id)&&has(nm(r),pto(r).nombre||'')).map(r=>({t:nm(r),s:(pto(r).nombre||'')+' · '+uname(r)+' · en el directorio',a:go_('directorio',{dq:nm(r)})})):[]));
 if(can('estructura.ver'))add('Estructura',[['unidades','Unidad'],['puestos','Puesto'],['sedes','Sede']].reduce((o,c)=>o.concat(T()[c[0]].filter(x=>x.activo!==false&&has(x.nombre)).map(x=>({t:x.nombre,s:c[1],a:`data-a="est" data-e="${c[0]}"`}))),[]));
 if(mOn('documentos'))add('Documentos',C('documentos').filter(d=>((ok('docs')&&scIds.has(d.relId))||(my&&d.relId===my.id))&&has(d.nombre||'',d.carpeta||'',relName(d.relId))).map(d=>({t:d.nombre,s:relName(d.relId)+' · '+d.carpeta+' · '+fd(d.fecha)+(d.estadoFirma==='Pendiente'?' · firma pendiente':''),a:allowed('ex_docs')?go_('ex_docs',{ex_dt:'repo'}):`data-a="ficha" data-id="${d.relId}"`})));
 if(ok('rec'))add('Vacantes',mRec(cx({})).vs.filter(v=>has(v.titulo,v.codigo||'',v.estado)).map(v=>({t:v.titulo,s:(v.codigo||'')+' · '+v.estado+' · '+((get('unidades',v.unidadId)||{}).nombre||''),a:go_('ta_vac',{ta_vac:v.id,ta_vt:ok('cand')?'tablero':'detalle',ta_lq:'',ta_lEst:''})})));
 if(ok('cand')){const vs=mRec(cx({})).vs;add('Candidatos',C('candidatos').filter(c=>vs.some(v=>v.id===c.vacanteId)&&has(c.nombre,c.correo||'',c.etapa)).map(c=>({t:c.nombre,s:((vs.find(v=>v.id===c.vacanteId)||{}).titulo||'')+' · '+c.etapa,a:go_('ta_cand',{ta_cand:c.id,ta_ct:'perfil'})})))}
 if(mOn('aprendizaje')&&can('aprendizaje.ver'))add('Cursos',C('cursos').filter(c=>c.activo!==false&&has(c.titulo,c.categoria||'')).map(c=>({t:c.titulo,s:(c.categoria||'')+' · '+c.horas+' h'+(c.obligatorio?' · obligatorio':''),a:go_('de_cursos',{})})));
 if(mOn('mesa'))add('Solicitudes',C('tickets').filter(t=>((ok('mesa')&&scIds.has(t.relId))||(my&&t.relId===my.id))&&has(t.codigo||'',t.asunto||'',t.categoria||'',relName(t.relId))).map(t=>({t:(t.codigo?t.codigo+' · ':'')+t.asunto,s:relName(t.relId)+' · '+t.categoria+' · '+t.estado,a:go_('ex_ticket',{ex_tk:t.id,navOpen:'Experiencia'})})));
 if(mOn('tiempo'))add('Vacaciones y permisos',C('vacSolicitudes').filter(v=>((ok('vac')&&scIds.has(v.relId))||(my&&v.relId===my.id))&&has('vacaciones',relName(v.relId),v.estado)).map(v=>({t:'Vacaciones de '+relName(v.relId),s:fd(v.desde)+' – '+fd(v.hasta)+' · '+v.estado,a:go_('ti_vacaciones',{})})).concat(C('ausencias').filter(a=>((ok('vac')&&scIds.has(a.relId))||(my&&a.relId===my.id))&&has('permiso ausencia',relName(a.relId),a.estado)).map(a=>({t:'Ausencia de '+relName(a.relId),s:fd(a.desde)+' – '+fd(a.hasta)+' · '+a.estado,a:go_('ti_ausencias',{})}))));
 if(hasA()&&can(PRV))add('Reportes',REPS.filter(r=>repOk(r)&&has(r.n,r.d,r.cat)).map(r=>({t:r.n,s:'Reporte predefinido · '+r.cat,a:`data-a="in_repOpen" data-id="${r.id}"`})).concat(misReps().filter(r=>has(r.nombre,r.desc||'')).map(r=>({t:r.nombre,s:'Reporte personalizado · '+(r.ownerNombre||''),a:`data-a="in_repOpen" data-id="c:${r.id}"`}))));
 if(mOn('experiencia'))add('Comunicados',C('ex_comunicados').filter(c=>c.estado==='Publicado'&&has(c.titulo||'',c.tipo||'')).map(c=>({t:c.titulo,s:c.tipo+' · '+fd(c.fecha),a:go_('ex_com',{})})));
 if(mOn('mesa'))add('Artículos de ayuda',C('ex_kb').filter(k=>has(k.titulo||'',k.claves||'')).map(k=>({t:k.titulo,s:'Base de conocimiento · '+(k.categoria||''),a:go_('ex_mesa',{})})));
 return out}
function vBuscar(){const q=U('in_bq',''),res=buscar(q),tot=sum(res,g=>g.n);
 return pageHead('Analytics','Buscar en todo','','Personas, estructura, documentos, vacantes, candidatos, cursos, solicitudes y reportes. Solo aparece lo que tu rol y tu alcance permiten ver.')
 +`<input class="in" id="in_bqI" data-inbq="1" placeholder="Escribe al menos 2 letras: un nombre, un documento, una vacante, un curso…" value="${esc(q)}" autocomplete="off" aria-label="Buscar en todo" style="font-size:16px;padding:11px 14px">`
 +(q.trim().length<2?`<div class="panel">${emptyState('¿Qué estás buscando?','Prueba con «contrato», «Sofía», «ventas», «seguridad» o «vacaciones».')}</div>`:!res.length?`<div class="panel">${emptyState('Sin resultados para «'+q+'»','No hay coincidencias dentro de tu alcance y tus permisos. Revisa la ortografía o prueba con menos palabras.')}</div>`
 :`<p class="muted">${pl(tot,'resultado')} en ${pl(res.length,'categoría')}.</p><div class="grid g2" style="align-items:start">${res.map(g=>`<div class="panel"><div class="ph"><h2 style="font-size:15px">${esc(g.cat)}</h2><span class="pill">${g.n}</span></div><div class="in_hb" style="padding:8px;gap:2px">${g.items.map(i=>`<button ${i.a} style="padding:8px 10px"><b>${esc(i.t)}</b><div class="muted" style="font-size:12.5px;overflow-wrap:anywhere">${esc(i.s)}</div></button>`).join('')}${g.n>g.items.length?`<span class="muted" style="padding:6px 10px;font-size:12.5px">Y ${g.n-g.items.length} más: afina la búsqueda.</span>`:''}</div></div>`).join('')}</div>`)}

