/* personas cuyo calendario «público» puede ver el usuario: su alcance + su equipo cercano (misma unidad, mismo jefe, su jefe y sus reportes) */
function calPool(){const sc=scoped();if(role().alcance==='todos')return sc;const my=myRel();if(!my)return sc;const u=(uniOf(my)||{}).id;
 const team=T().relaciones.filter(r=>r.estado==='Activo'&&((u&&(uniOf(r)||{}).id===u)||(my.jefeId&&r.jefeId===my.jefeId)||r.jefeId===my.id||r.id===my.jefeId));return[...new Set(sc.concat(team))]}
function calEvents(d,h){const out=[],scId=new Set(scoped().map(r=>r.id)),us=ui.in_cUni?unitSet(ui.in_cUni):null,my=myRel(),todos=role().alcance==='todos';
 const P=calPool().filter(r=>(!ui.emp||r.empresaId===ui.emp)&&(!us||us.includes((uniOf(r)||{}).id))),pid=new Set(P.map(r=>r.id)),full=id=>scId.has(id)||(my&&my.id===id);
 const push=(f,t,l,o)=>{if(f&&f>=d&&f<=h)out.push({f,t,l,...(o||{})})};
 const span=(a,b,t,l,o)=>{let x=a<d?d:a,n=0;const e=b>h?h:b,rg=a===b?'':fd(a).slice(0,5)+' – '+fd(b).slice(0,5);while(x<=e&&n++<70){out.push({f:x,t,l,rango:rg,...(o||{})});x=addDays(x,1)}};
 const ys=[...new Set([d.slice(0,4),h.slice(0,4)])];
 if(mOn('tiempo')){C('vacSolicitudes').filter(v=>pid.has(v.relId)&&(v.estado==='Aprobada'||(v.estado==='Pendiente'&&full(v.relId)&&(ok('vac')||(my&&my.id===v.relId))))).forEach(v=>span(v.desde,v.hasta,'vac','Vacaciones · '+relName(v.relId)+(v.estado==='Pendiente'?' (por aprobar)':''),{rel:v.relId}));
  C('ausencias').filter(a=>pid.has(a.relId)&&a.estado==='Aprobada').forEach(a=>{const det=(ok('vac')&&scId.has(a.relId))||(my&&my.id===a.relId);span(a.desde,a.hasta,'aus',(det?a.tipo||'Ausencia':'Fuera de la oficina')+' · '+relName(a.relId),{rel:a.relId})});
  C('feriados').forEach(f=>push(f.fecha,'fer','Feriado · '+f.nombre))}
 P.filter(r=>r.estado==='Activo').forEach(r=>{const nac=per(r).nacimiento;ys.forEach(y=>{if(nac)push(y+nac.slice(4),'cum','Cumpleaños · '+nm(r),{rel:r.id});if(r.ingreso.slice(0,4)<y)push(y+r.ingreso.slice(4),'ani',pl(+y-+r.ingreso.slice(0,4),'año')+' en la empresa · '+nm(r),{rel:r.id})})});
 P.filter(r=>r.estado==='Activo'&&r.contratoFin&&full(r.id)).forEach(r=>push(r.contratoFin,'con','Vence el contrato · '+nm(r),{rel:r.id}));
 if(mOn('aprendizaje')){const cs=C('cursos'),g={};C('inscripciones').filter(i=>pid.has(i.relId)&&i.estado!=='Completado'&&i.vence&&((ok('apr')&&scId.has(i.relId))||(my&&my.id===i.relId))).forEach(i=>{const k=i.vence+'|'+i.cursoId;(g[k]=g[k]||[]).push(i)});
  Object.entries(g).forEach(([k,is])=>{const cu=cs.find(c=>c.id===is[0].cursoId)||{};push(is[0].vence,'cap','Vence el curso «'+(cu.titulo||'')+'» · '+(is.length===1?relName(is[0].relId):is.length+' personas'),is.length===1?{rel:is[0].relId}:{sub:is.map(i=>relName(i.relId)).join(', ')})})}
 if(ok('sst'))C('op_sstCapac').filter(x=>!ui.emp||(get('sedes',x.sedeId)||{}).empresaId===ui.emp).forEach(x=>push(x.fecha,'cap','Capacitación de SST · '+x.tema,{sub:(get('sedes',x.sedeId)||{}).nombre||''}));
 if(mOn('desempeno')&&can('desempeno.ver'))C('evalCiclos').filter(c=>c.estado!=='Borrador'&&(todos||ok('desem')||(my&&(c.participantes||[]).includes(my.id)))).forEach(c=>{push(c.desde,'eva','Inicio de «'+c.nombre+'»');push(c.hasta,'eva','Cierre de «'+c.nombre+'»')});
 if(mOn('reclutamiento'))C('ta_entrevistas').filter(e=>e.estado!=='Cancelada'&&(ok('cand')||(e.entrevistadores||[]).includes(me().id))).forEach(e=>{const cd=C('candidatos').find(c=>c.id===e.candId)||{},v=C('vacantes').find(x=>x.id===e.vacanteId)||{};if((!ui.emp||v.empresaId===ui.emp)&&(!us||us.includes(v.unidadId)))push(e.fecha,'ent',(e.hora?e.hora+' · ':'')+(e.tipo||'Entrevista')+' · '+(cd.nombre||''),{sub:(v.titulo||'')+(e.lugar?' · '+e.lugar:'')})});
 const segOk=(emp,uni)=>(!ui.emp||!emp||emp===ui.emp)&&(!us||!uni||us.includes(uni))&&(todos||!my||((!emp||emp===my.empresaId)&&(!uni||unitSet(uni).includes((uniOf(my)||{}).id))));
 C('in_eventos').filter(e=>(e.publico||can(PCA))&&segOk(e.empresaId,e.unidadId)).forEach(e=>span(e.fecha,e.hasta||e.fecha,'evt',(e.hora?e.hora+' · ':'')+e.titulo,{ev:e.id,sub:[e.tipo,e.lugar,e.publico?'':'Solo RRHH'].filter(Boolean).join(' · ')}));
 if(mOn('experiencia'))C('ex_comunicados').filter(c=>c.tipo==='Evento'&&c.estado==='Publicado'&&c.fechaEvento&&segOk((c.seg||{}).empresaId,(c.seg||{}).unidadId)).forEach(c=>push(c.fechaEvento,'evt',(c.hora?c.hora+' · ':'')+c.titulo,{sub:['Evento de Comunicaciones',c.lugar].filter(Boolean).join(' · ')}));
 const off=U('in_cOff',{});return out.filter(e=>!off[e.t]).sort((a,b)=>a.f.localeCompare(b.f)||TY.findIndex(t=>t[0]===a.t)-TY.findIndex(t=>t[0]===b.t)||a.l.localeCompare(b.l,'es'))}
const evRow=e=>{const sc=e.rel&&scoped().some(r=>r.id===e.rel),inner=`<span class="in_ev t-${e.t}" style="flex:none">${esc(tyN(e.t))}</span><span style="min-width:0;flex:1"><b style="overflow-wrap:anywhere">${esc(e.l)}</b>${e.rango||e.sub?`<div class="muted" style="font-size:12.5px">${esc([e.rango,e.sub].filter(Boolean).join(' · '))}</div>`:''}</span>`;
 return `<div class="row" style="flex-wrap:nowrap;align-items:flex-start;padding:7px 0">${inner}${sc?`<button class="btn s" data-a="in_ficha" data-id="${e.rel}">Ficha</button>`:''}${e.ev&&can(PCA)?`<button class="btn s" data-a="in_evEdit" data-id="${e.ev}">Editar</button>`:''}</div>`};
function vCalendario(){const ym=U('in_cYM',TODAY.slice(0,7)),y=+ym.slice(0,4),m=+ym.slice(5,7)-1,view=U('in_cView','mes'),first=ym+'-01',last=iso(new Date(y,m+1,0));
 const gi=addDays(first,-((new Date(first+'T12:00:00').getDay()+6)%7)),ge=addDays(last,(7-new Date(last+'T12:00:00').getDay())%7),evs=calEvents(view==='mes'?gi:first,view==='mes'?ge:last),off=U('in_cOff',{}),by={};evs.forEach(e=>(by[e.f]=by[e.f]||[]).push(e));
 const al=role().alcance,head=pageHead('',`Calendario de RRHH`,`<div class="row" style="gap:4px"><button class="btn" data-a="in_cNav" data-d="-1" aria-label="Mes anterior">‹</button><button class="btn" data-a="in_cNav" data-d="0">Hoy</button><button class="btn" data-a="in_cNav" data-d="1" aria-label="Mes siguiente">›</button></div><div class="row" style="gap:4px"><button class="btn ${view==='mes'?'p':''}" data-a="in_cView" data-v="mes">Mes</button><button class="btn ${view==='lista'?'p':''}" data-a="in_cView" data-v="lista">Lista</button></div>${can(PCA)?'<button class="btn p" data-a="in_evNew">Nuevo evento</button>':''}`,al==='todos'?'Vacaciones, ausencias, cumpleaños, contratos, capacitaciones, evaluaciones, entrevistas, feriados y eventos de toda la organización.':al==='equipo'?'Ves todo lo de tu equipo y lo público de tus compañeros de unidad.':'Ves lo tuyo y lo público de tu equipo: vacaciones, ausencias (sin el motivo), cumpleaños, feriados y eventos.');
 const filt=`<div class="panel"><div class="pb" style="display:flex;flex-direction:column;gap:10px"><div class="row" style="justify-content:space-between"><h2 style="text-transform:capitalize">${MESL[m]} ${y}</h2><div class="row">${sel('id="in_cEmp" data-c="emp" aria-label="Empresa" style="width:auto;max-width:220px"',ui.emp,T().empresas.filter(e=>e.activo).map(e=>[e.id,e.nombre]),'Todas las empresas')}${sel('id="in_cUni" data-c="in_cUni" aria-label="Unidad" style="width:auto;max-width:220px"',U('in_cUni',''),opt('unidades'),'Todas las unidades')}</div></div>
 <div class="in_chips" role="group" aria-label="Tipos de evento">${TY.map(t=>`<button class="in_chip ${off[t[0]]?'':'on'}" data-a="in_cType" data-t="${t[0]}" aria-pressed="${!off[t[0]]}"><span class="in_dots" style="display:flex"><i class="t-${t[0]}"></i></span>${t[1]}</button>`).join('')}</div></div></div>`;
 let b='';
 if(view==='mes'){let cells='',x=gi,n=0;while(x<=ge&&n++<42){const es=by[x]||[],o=x.slice(0,7)!==ym;cells+=`<button class="in_day${o?' in_out':''}${x===TODAY?' in_hoy':''}" data-a="in_cDay" data-f="${x}" aria-label="${fd(x)}: ${pl(es.length,'evento')}"><span class="in_dn">${+x.slice(8)}</span>${es.slice(0,3).map(e=>`<span class="in_ev t-${e.t}" title="${esc(e.l)}">${esc(e.l)}</span>`).join('')}${es.length>3?`<span class="in_ev muted">+${es.length-3} más</span>`:''}<span class="in_dots">${es.slice(0,6).map(e=>`<i class="t-${e.t}"></i>`).join('')}</span></button>`;x=addDays(x,1)}
  b=`<div class="panel" style="overflow:hidden"><div class="in_cal">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(dn=>`<div class="in_dh">${dn}</div>`).join('')}${cells}</div></div><p class="muted" style="font-size:12.5px">Toca un día para ver el detalle${can(PCA)?' o crear un evento en esa fecha':''}.</p>`}
 else{const ds=Object.keys(by).sort();b=`<div class="panel">${ds.length?ds.map(f=>`<div class="pb" style="border-bottom:1px solid var(--line);padding-block:10px"><div class="row" style="justify-content:space-between"><b>${DIAS[new Date(f+'T12:00:00').getDay()]} ${+f.slice(8)} de ${MESL[+f.slice(5,7)-1]}</b>${f===TODAY?pill('Hoy','acc'):''}</div>${by[f].map(evRow).join('')}</div>`).join(''):emptyState('Nada en el calendario de este mes','Prueba con otro mes, activa más tipos de evento o quita el filtro de unidad.',can(PCA)?'<button class="btn p" data-a="in_evNew">Nuevo evento</button>':'')}</div>`}
 return head+filt+b}
function evForm(id,fecha){const e=id?C('in_eventos').find(x=>x.id===id):null;
 openForm(()=>({title:e?'Editar evento':'Nuevo evento de RRHH',fields:[{k:'titulo',l:'Título',req:1,full:1},{k:'tipo',l:'Tipo',opts:['Evento','Reunión','Capacitación','Fecha clave'],req:1,keep:1},{k:'fecha',l:'Fecha',type:'date',req:1},{k:'hasta',l:'Hasta (si dura varios días)',type:'date'},{k:'hora',l:'Hora',type:'time'},{k:'lugar',l:'Lugar o enlace'},{k:'empresaId',l:'Solo para la empresa',opts:opt('empresas')},{k:'unidadId',l:'Solo para la unidad',opts:opt('unidades')},{k:'vis',l:'Quién lo ve',opts:[['1','Todos los que ven el calendario'],['0','Solo quienes administran el calendario']],req:1,keep:1},{k:'descripcion',l:'Descripción',type:'textarea',full:1}],
  submit:o=>{if(o.hasta&&o.hasta<o.fecha)return 'La fecha final no puede ser anterior a la inicial.';if(o.hasta&&days(o.fecha,o.hasta)>60)return 'Un evento no puede durar más de 60 días.';
   const d={titulo:o.titulo,tipo:o.tipo,fecha:o.fecha,hasta:o.hasta||'',hora:o.hora||'',lugar:o.lugar||'',empresaId:o.empresaId||'',unidadId:o.unidadId||'',publico:o.vis==='1',descripcion:o.descripcion||''};
   if(e){Object.assign(e,d);log('Edición','Calendario',e.titulo,e.id,'',fd(e.fecha))}else{const n={id:nid('inv'),por:me().nombre,creado:TODAY,...d};T().in_eventos.push(n);log('Alta','Calendario',n.titulo,n.id,'',fd(n.fecha))}
   ui.in_cYM=o.fecha.slice(0,7);toast('Evento guardado')}}),e?{...e,vis:e.publico?'1':'0'}:{tipo:'Evento',fecha:fecha||TODAY,vis:'1'})}

