function home(){if(!can(PV)||role().alcance!=='todos'||!T().relaciones.length)return'';const c=cx({}),I=inds(c),S=serieDot(c),mini=(i,sp)=>i&&!i.g?`<div class="in_tile"><span class="in_l">${esc(i.l)}</span><span class="in_v num">${i.v}</span><span class="in_s">${i.sub||''}</span>${sp&&sp.length>1?spark(sp):''}</div>`:'';
 let k3=mini(I.antig),k4=mini(I.contr);
 if(ok('costo')){const K=mCosto(c);k3=mini(I.costo,K.nom?K.nom.ks.map(k=>sum(K.nom.by[k],K.costoDe)):null)}else if(ok('tiempo'))k3=mini(I.aus);
 if(ok('exp')){const X=mExp(c);k4=mini(I.enps,X.en.filter(x=>!x.oculto).map(x=>x.v))}else if(ok('apr'))k4=mini(I.cap);
 return `<div class="panel"><div class="ph"><div><h2>Indicadores clave</h2><span class="muted" style="font-size:12.5px">Últimos 12 meses · con la tendencia mensual</span></div><div class="row">${(na=>can(PAV)&&na?`<button class="btn s" data-a="nav" data-r="in_alertas">${pl(na,'alerta inteligente','alertas inteligentes')}</button>`:'')(can(PAV)?nAlertas():0)}<button class="btn s p" data-a="nav" data-r="in_analytics">Abrir People Analytics</button></div></div><div class="pb"><div class="in_tiles">${mini(I.hc,S.map(x=>x.hc))}${mini(I.rot,S.map(x=>x.ba))}${k3}${k4}</div></div></div>`}

