const repDoc=(rp,res)=>`<div class="in_doc"><div class="row" style="justify-content:space-between;align-items:flex-start;border-bottom:2px solid var(--ink);padding-bottom:10px;margin-bottom:14px"><div><div class="in_tag">${esc(tenant().nombre)}</div><h2 style="font-size:20px">${esc(rp.n)}</h2><div class="muted">${esc(rp.d)}</div></div><div class="muted" style="text-align:right;font-size:12.5px">Generado el ${fd(TODAY)}<br>por ${esc(me().nombre)}<br>${pl(res.rows.length,'fila')}</div></div>${resTable({cols:res.cols,rows:res.rows.slice(0,60)},1,0)}${res.rows.length>60?`<p class="muted" style="margin-top:8px">Se muestran las primeras 60 filas de ${res.rows.length}.</p>`:''}<p class="muted" style="margin-top:14px;font-size:12px">Documento confidencial de uso interno. Contiene solo los datos que el rol «${esc(role().nombre)}» puede ver.</p></div>`;
